package com.jinloes.practice;
class Workload { static final String UNIT="nodes"; static final int[] SIZES={1000,2000,4000,8000}; static Object prepare(int size){ Solution.TreeNode root=new Solution.TreeNode(0), l=root; for(int i=1;i<size/2;i++){ l.left=new Solution.TreeNode(i); l=l.left; } Solution.TreeNode r=root; for(int i=size/2;i<size;i++){ r.right=new Solution.TreeNode(i); r=r.right; } return new Object[]{root,l,r}; } static void run(Object st){ Object[] d=(Object[])st; if(Solution.lowestCommonAncestor((Solution.TreeNode)d[0],(Solution.TreeNode)d[1],(Solution.TreeNode)d[2])==null) throw new IllegalStateException(); } static int units(int size){ return size; } }
